import{_ as e,c as o,a2 as t,o as r}from"./chunks/framework.GMKO7RMU.js";const b=JSON.parse('{"title":"购买的Facebook账号使用教程","description":"","frontmatter":{"title":"购买的Facebook账号使用教程"},"headers":[],"relativePath":"KnowledgeBase/外贸相关/购买的Facebook账号使用教程.md","filePath":"KnowledgeBase/外贸相关/购买的Facebook账号使用教程.md","lastUpdated":1785065613000}'),l={name:"KnowledgeBase/外贸相关/购买的Facebook账号使用教程.md"};function n(i,a,p,c,d,h){return r(),o("div",null,a[0]||(a[0]=[t('<h1 id="购买的facebook账号使用教程" tabindex="-1">购买的Facebook账号使用教程 <a class="header-anchor" href="#购买的facebook账号使用教程" aria-label="Permalink to &quot;购买的Facebook账号使用教程&quot;">​</a></h1><h2 id="手机端app登录-推荐" tabindex="-1">手机端app登录(推荐) <a class="header-anchor" href="#手机端app登录-推荐" aria-label="Permalink to &quot;手机端app登录(推荐)&quot;">​</a></h2><h3 id="第一步-输入账号与密码" tabindex="-1">第一步：输入账号与密码 <a class="header-anchor" href="#第一步-输入账号与密码" aria-label="Permalink to &quot;第一步：输入账号与密码&quot;">​</a></h3><p>打开 Facebook App，输入邮箱和密码后点击登录。</p><h3 id="第二步-跳过设备通知验证" tabindex="-1">第二步：跳过设备通知验证 <a class="header-anchor" href="#第二步-跳过设备通知验证" aria-label="Permalink to &quot;第二步：跳过设备通知验证&quot;">​</a></h3><p>首次登录时，Facebook 通常会显示「在另一台设备上查看通知」页面， 要求在原有设备上批准登录。由于你是新接手的账号，不持有原始设备， 直接点击下方的「试试其他方式」。</p><h3 id="第三步-选择身份验证应用" tabindex="-1">第三步：选择身份验证应用 <a class="header-anchor" href="#第三步-选择身份验证应用" aria-label="Permalink to &quot;第三步：选择身份验证应用&quot;">​</a></h3><p>页面会展示可用的验证方式列表，选择「身份验证应用」， 然后点击「继续」。</p><h3 id="💡-提示" tabindex="-1">💡 提示 <a class="header-anchor" href="#💡-提示" aria-label="Permalink to &quot;💡 提示&quot;">​</a></h3><p>「身份验证应用」选项对应的就是 2FA 密钥， 打开 2fa.run， 粘贴 2FA 密钥生成 6 位验证码后填入即可完成登录。</p><h3 id="登录后注意事项" tabindex="-1">登录后注意事项 <a class="header-anchor" href="#登录后注意事项" aria-label="Permalink to &quot;登录后注意事项&quot;">​</a></h3><p>✅ 建议的养号操作</p><p>• 登录后先浏览信息流、观看视频，模拟真实用户行为</p><p>• 接收到 BM（商务管理平台）后，24 小时内不要进行任何操作，先挂机养号</p><p>• 至少正常使用 3 天后，再修改密码或其他敏感信息</p><p>• 始终保持 IP 稳定，不要在同一会话内切换节点</p>',16)]))}const k=e(l,[["render",n]]);export{b as __pageData,k as default};
